create table public.entitlement_plans (id uuid primary key default gen_random_uuid(),code text not null unique check (code=lower(code) and char_length(btrim(code))>0),name text not null check(char_length(btrim(name))>0),description text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.entitlement_plan_features (id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.entitlement_plans(id) on delete cascade,feature_key text not null check(char_length(btrim(feature_key))>0),enabled boolean not null default true,numeric_limit integer check(numeric_limit is null or numeric_limit>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(plan_id,feature_key));
create table public.user_entitlements (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,plan_id uuid not null references public.entitlement_plans(id) on delete restrict,status text not null default 'active' check(status in ('active','trialing','past_due','canceled','expired')),starts_at timestamptz not null default now(),ends_at timestamptz,external_customer_id text,external_subscription_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at));
create unique index user_entitlements_one_current_idx on public.user_entitlements(user_id) where status in ('active','trialing','past_due');
create index user_entitlements_plan_id_idx on public.user_entitlements(plan_id);
create index entitlement_plan_features_feature_key_idx on public.entitlement_plan_features(feature_key);
insert into public.entitlement_plans(code,name,description) values('free','Free','Default plan for users without a paid subscription.');
insert into public.entitlement_plan_features(plan_id,feature_key,enabled,numeric_limit) select id,'coach.max_teams',true,null::integer from public.entitlement_plans where code='free' union all select id,'athlete.max_teams',true,null::integer from public.entitlement_plans where code='free';
alter table public.entitlement_plans enable row level security; alter table public.entitlement_plan_features enable row level security; alter table public.user_entitlements enable row level security;
create policy entitlement_plans_select_authenticated on public.entitlement_plans for select to authenticated using(is_active=true or private.is_admin((select auth.uid())));
create policy entitlement_plan_features_select_authenticated on public.entitlement_plan_features for select to authenticated using(exists(select 1 from public.entitlement_plans p where p.id=plan_id and (p.is_active=true or private.is_admin((select auth.uid())))));
create policy user_entitlements_select_self_or_admin on public.user_entitlements for select to authenticated using(user_id=(select auth.uid()) or private.is_admin((select auth.uid())));
create policy entitlement_plans_admin_all on public.entitlement_plans for all to authenticated using(private.is_admin((select auth.uid()))) with check(private.is_admin((select auth.uid())));
create policy entitlement_plan_features_admin_all on public.entitlement_plan_features for all to authenticated using(private.is_admin((select auth.uid()))) with check(private.is_admin((select auth.uid())));
create policy user_entitlements_admin_all on public.user_entitlements for all to authenticated using(private.is_admin((select auth.uid()))) with check(private.is_admin((select auth.uid())));
create trigger entitlement_plans_set_updated_at before update on public.entitlement_plans for each row execute function private.set_updated_at();
create trigger entitlement_plan_features_set_updated_at before update on public.entitlement_plan_features for each row execute function private.set_updated_at();
create trigger user_entitlements_set_updated_at before update on public.user_entitlements for each row execute function private.set_updated_at();
